package com.fakelegacy.customer;

import java.math.BigDecimal;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class LoyaltyController {

    private static final BigDecimal POINT_VALUE = new BigDecimal("0.05");
    private static final BigDecimal MAX_SHARE = new BigDecimal("0.5");

    @Autowired
    private CustomerDao customerDao;
    @Autowired
    private LoyaltyDao loyaltyDao;

    // U4
    @GetMapping("/customers/{id}/loyalty")
    public Map<String, Object> balance(@PathVariable("id") long id) {
        if (customerDao.findById(id) == null) {
            return Responses.error("customer not found");
        }
        Map<String, Object> res = Responses.ok();
        res.put("customerId", id);
        res.put("points", loyaltyDao.balance(id));
        return res;
    }

    // U5: negative points are accepted (clawback)
    @PostMapping("/customers/{id}/loyalty/earn")
    @Transactional
    public Map<String, Object> earn(@PathVariable("id") long id, @RequestBody Map<String, Object> body) {
        Customer c = customerDao.findById(id);
        if (c == null) {
            return Responses.error("customer not found");
        }
        Integer points = toInt(body.get("points"));
        if (points == null || points == 0) {
            return Responses.error("points must be a non-zero integer");
        }
        int credited = loyaltyDao.earn(c, points, orderRef(body));
        Map<String, Object> res = Responses.ok();
        res.put("customerId", id);
        res.put("credited", credited);
        res.put("balance", loyaltyDao.balance(id));
        return res;
    }

    // U6: negative points give previously redeemed points back
    @PostMapping("/customers/{id}/loyalty/redeem")
    @Transactional
    public Map<String, Object> redeem(@PathVariable("id") long id, @RequestBody Map<String, Object> body) {
        if (customerDao.findById(id) == null) {
            return Responses.error("customer not found");
        }
        Integer points = toInt(body.get("points"));
        if (points == null || points == 0) {
            return Responses.error("points must be a non-zero integer");
        }
        if (points > 0) {
            if (body.get("orderAmount") == null) {
                return Responses.error("orderAmount is required to redeem points");
            }
            BigDecimal orderAmount;
            try {
                orderAmount = new BigDecimal(String.valueOf(body.get("orderAmount")));
            } catch (NumberFormatException e) {
                return Responses.error("orderAmount is not a number");
            }
            BigDecimal value = POINT_VALUE.multiply(BigDecimal.valueOf(points));
            if (value.compareTo(orderAmount.multiply(MAX_SHARE)) > 0) {
                return Responses.error("points cannot cover more than 50% of the order amount");
            }
        }
        if (!loyaltyDao.redeem(id, points, orderRef(body))) {
            return Responses.error("insufficient loyalty balance");
        }
        Map<String, Object> res = Responses.ok();
        res.put("customerId", id);
        res.put("balance", loyaltyDao.balance(id));
        return res;
    }

    private static String orderRef(Map<String, Object> body) {
        Object o = body.get("orderRef");
        return o == null ? null : String.valueOf(o);
    }

    private static Integer toInt(Object o) {
        if (o == null) {
            return null;
        }
        try {
            return new BigDecimal(String.valueOf(o)).intValueExact();
        } catch (ArithmeticException | NumberFormatException e) {
            return null;
        }
    }
}
